  1	use std::collections::BTreeMap;
  2	
  3	pub struct Item {
  4	    pub item_type: String,
  5	    pub material: String,
  6	    pub enchantment: u32,
  7	    pub cursed: bool,
  8	}
  9	
 10	const PROCESSING_FEE: u64 = 5;
 11	
 12	const SWORD_BASE_PREMIUM: u64 = 100;
 13	const AMULET_BASE_PREMIUM: u64 = 60;
 14	const STAFF_BASE_PREMIUM: u64 = 80;
 15	const POTION_BASE_PREMIUM: u64 = 40;
 16	const COMPONENT_BASE_PREMIUM: u64 = 25;
 17	const COMPONENT_BLOCK_BASE_PREMIUM: u64 = 60;
 18	const COMPONENT_BLOCK_SIZE: usize = 3;
 19	const FIRST_INSURANCE_SURCHARGE_PERCENT: u64 = 10;
 20	
 21	/// The MHPCO price list: the base premium the catalogue lists for one item.
 22	fn base_premium(item: &Item) -> u64 {
 23	    match item.item_type.as_str() {
 24	        "amulet" => AMULET_BASE_PREMIUM,
 25	        "staff" => STAFF_BASE_PREMIUM,
 26	        "potion" => POTION_BASE_PREMIUM,
 27	        "rune" | "moonstone" => COMPONENT_BASE_PREMIUM,
 28	        _ => SWORD_BASE_PREMIUM,
 29	    }
 30	}
 31	
 32	/// The building-block offer is reserved for a group of exactly 3 alike
 33	/// components; a larger group does not qualify, it is priced per component.
 34	fn qualifies_as_building_block(alike_component_count: usize) -> bool {
 35	    alike_component_count == COMPONENT_BLOCK_SIZE
 36	}
 37	
 38	/// A building block of 3 alike components is offered at a special base
 39	/// premium. "Alike" means components of the very same catalogue type.
 40	fn component_group_base_premium(count: usize) -> u64 {
 41	    if qualifies_as_building_block(count) {
 42	        COMPONENT_BLOCK_BASE_PREMIUM
 43	    } else {
 44	        count as u64 * COMPONENT_BASE_PREMIUM
 45	    }
 46	}
 47	
 48	/// Two components are "alike" when they share this key. The MHPCO reads
 49	/// "alike" as the very same catalogue type, not a wider family of components.
 50	fn alike_group_key(item: &Item) -> &str {
 51	    &item.item_type
 52	}
 53	
 54	/// The policy base premium: the sum of all insured items' base premiums,
 55	/// with alike components priced per group so a block can be recognised.
 56	fn policy_base_premium(items: &[Item]) -> u64 {
 57	    let mut main_items_total = 0;
 58	    let mut alike_component_counts: BTreeMap<&str, usize> = BTreeMap::new();
 59	    for item in items {
 60	        if is_component(item) {
 61	            *alike_component_counts.entry(alike_group_key(item)).or_insert(0) += 1;
 62	        } else {
 63	            main_items_total += base_premium(item);
 64	        }
 65	    }
 66	
 67	    main_items_total
 68	        + alike_component_counts
 69	            .values()
 70	            .map(|count| component_group_base_premium(*count))
 71	            .sum::<u64>()
 72	}
 73	
 74	/// Components, such as runes and moonstones, are the parts the MHPCO insures
 75	/// alongside main items and the only items the building-block offer covers.
 76	fn is_component(item: &Item) -> bool {
 77	    matches!(item.item_type.as_str(), "rune" | "moonstone")
 78	}
 79	
 80	/// Intermediate amounts stay fractional; only the final premium is rounded.
 81	/// In the MHPCO's favor means upwards for a premium the customer owes.
 82	fn premium_rounded_in_mhpco_favor(amount: f64) -> u64 {
 83	    amount.ceil() as u64
 84	}
 85	
 86	/// Every item in a quote is treated as a first insurance, so the initial
 87	/// assessment surcharge is charged on the whole policy base premium.
 88	fn first_insurance_surcharge(policy_base_premium: f64) -> f64 {
 89	    policy_base_premium * FIRST_INSURANCE_SURCHARGE_PERCENT as f64 / 100.0
 90	}
 91	
 92	pub fn quote_premium(items: &[Item]) -> u64 {
 93	    let policy_base_premium = policy_base_premium(items) as f64;
 94	    premium_rounded_in_mhpco_favor(
 95	        policy_base_premium + first_insurance_surcharge(policy_base_premium) + PROCESSING_FEE as f64,
 96	    )
 97	}
