59	    let mut alike_component_counts: BTreeMap<&str, usize> = BTreeMap::new();
60	    for item in items {
61	        if is_component(item) {
62	            *alike_component_counts.entry(alike_group_key(item)).or_insert(0) += 1;
63	        } else {
64	            main_items_total += base_premium(item);
65	        }
66	    }
